record PageProfil(Utilisateur profil, List<Commande> commandes) { }

PageProfil chargerPage(String id) throws Exception {
    try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
        Subtask<Utilisateur> profil = scope.fork(() -> serviceProfil.get(id));
        Subtask<List<Commande>> commandes = scope.fork(() -> serviceCommandes.get(id));
        scope.join();
        scope.throwIfFailed();
        return new PageProfil(profil.get(), commandes.get());
    }
}
